import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.DCk0k6gb.js";const k=JSON.parse('{"title":"迁移到 0.2.0","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/migration-0.2.md","filePath":"zh/guide/migration-0.2.md"}'),o={name:"zh/guide/migration-0.2.md"};function n(d,e,r,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="迁移到-0-2-0" tabindex="-1">迁移到 0.2.0 <a class="header-anchor" href="#迁移到-0-2-0" aria-label="Permalink to &quot;迁移到 0.2.0&quot;">​</a></h1><p><a href="/sa-token-rust/guide/migration-0.2.html">English</a></p><p>从 0.1.x 升到 0.2.0 时，请按本页核对行为变更与 API 替换。完整双语文档亦在仓库根目录 <a href="https://github.com/sa-tokens/sa-token-rust/blob/main/MIGRATION_0.2.md" target="_blank" rel="noreferrer">MIGRATION_0.2.md</a>。</p><p>设计灵感来自 Dromara sa-token；本仓库为独立实现（MIT OR Apache-2.0），见 <code>NOTICE</code>。</p><h2 id="可能静默影响生产的行为" tabindex="-1">可能静默影响生产的行为 <a class="header-anchor" href="#可能静默影响生产的行为" aria-label="Permalink to &quot;可能静默影响生产的行为&quot;">​</a></h2><h3 id="auto-renew-默认-false" tabindex="-1"><code>auto_renew</code> 默认 <code>false</code> <a class="header-anchor" href="#auto-renew-默认-false" aria-label="Permalink to &quot;`auto_renew` 默认 `false`&quot;">​</a></h3><p>0.1.x 读 token 可能写回 TTL。0.2.0 默认关闭，避免每次读取都写存储。需要旧行为时显式开启：</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(storage)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auto_renew</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renew_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">try_build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="is-read-真正生效" tabindex="-1"><code>is_read_*</code> 真正生效 <a class="header-anchor" href="#is-read-真正生效" aria-label="Permalink to &quot;`is_read_*` 真正生效&quot;">​</a></h3><p><code>is_read_header</code> / <code>is_read_cookie</code> / <code>is_read_body</code> 经 <code>token_io::read_token</code> 控制适配器如何取 token。生产若只走 Header，不要关掉 <code>is_read_header</code>。</p><h3 id="jwt" tabindex="-1">JWT <a class="header-anchor" href="#jwt" aria-label="Permalink to &quot;JWT&quot;">​</a></h3><ul><li>使用 <code>TokenStyle::Jwt</code> 但缺少 / 空 <code>jwt_secret_key</code> 时，<code>try_build</code> / <code>TokenGenerator</code> 返回 <code>Err(SaTokenError::ConfigError)</code>，库路径不再 panic。</li><li><code>jwt_fallback_on_error</code> 默认 <code>false</code>。JWT 失败不再悄悄变成 UUID。</li></ul><h3 id="sa-ignore-不跳过中间件" tabindex="-1"><code>#[sa_ignore]</code> 不跳过中间件 <a class="header-anchor" href="#sa-ignore-不跳过中间件" aria-label="Permalink to &quot;`#[sa_ignore]` 不跳过中间件&quot;">​</a></h3><p>公开路径必须写入 <code>PathAuthConfig::exclude</code>。该属性只跳过宏插入的校验，不会绕过 Layer / Middleware。</p><h3 id="在线用户是-presence" tabindex="-1">在线用户是 presence <a class="header-anchor" href="#在线用户是-presence" aria-label="Permalink to &quot;在线用户是 presence&quot;">​</a></h3><p><code>OnlineManager::new()</code> 仍是进程内。跨实例用 <code>with_distributed_online()</code>。HTTP 登录不会自动 <code>mark_online</code>。</p><h3 id="token-prefix-存在" tabindex="-1"><code>token_prefix</code>（存在） <a class="header-anchor" href="#token-prefix-存在" aria-label="Permalink to &quot;`token_prefix`（存在）&quot;">​</a></h3><p>可选配置：<code>.token_prefix(&quot;Bearer &quot;)</code>。</p><ul><li>读 token 时由 <code>token_io::apply_token_prefix</code> 应用。</li><li><code>None</code>（默认）仍剥离开头的 <code>Bearer </code>。</li><li>空字符串在 <code>try_build</code> 时拒绝。</li></ul><p>Token 键名仍是 <code>token_name</code>（默认 <code>&quot;sa-token&quot;</code>），与前缀是两回事。</p><h3 id="cookie-is-write-cookie-存在" tabindex="-1">Cookie：<code>is_write_cookie</code>（存在） <a class="header-anchor" href="#cookie-is-write-cookie-存在" aria-label="Permalink to &quot;Cookie：`is_write_cookie`（存在）&quot;">​</a></h3><p>登录不会自动 <code>Set-Cookie</code>。需要写 Cookie 时：</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(storage)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_write_cookie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cookie_http_only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">try_build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在响应路径调用 <code>write_token_cookie</code>；登出用 <code>delete_token_cookie</code>。开关为 <code>false</code>（默认）时二者为空操作。</p><h3 id="可插拔存储编码-saserializer" tabindex="-1">可插拔存储编码（<code>SaSerializer</code>） <a class="header-anchor" href="#可插拔存储编码-saserializer" aria-label="Permalink to &quot;可插拔存储编码（`SaSerializer`）&quot;">​</a></h3><p>TokenInfo、Session、Nonce、OAuth2/SSO 等存储载荷经 <code>SaTokenConfig.serializer</code>（<code>SharedSerializer</code>）。默认 JSON。可选二进制需 Cargo feature <code>fory</code>，并 <code>.serializer(SharedSerializer::from(ForySerializer::default()))</code>。Fory 仍可<strong>读取</strong>存量纯 JSON（滚动升级）；若已有二进制行再切回 JSON，会因格式不匹配失败。完整说明：<a href="./storage.html">存储</a>。</p><h2 id="已移除与替代" tabindex="-1">已移除与替代 <a class="header-anchor" href="#已移除与替代" aria-label="Permalink to &quot;已移除与替代&quot;">​</a></h2><table tabindex="0"><thead><tr><th>已移除 / 废弃</th><th>替代</th></tr></thead><tbody><tr><td><code>SaStorage::keys</code></td><td><code>SaStorage::scan</code> 直到 <code>next_cursor == 0</code></td></tr><tr><td>服务直接握 <code>SaStorage</code></td><td><code>SaTokenDao</code>（<code>set_object</code> / <code>get_object</code> / <code>cas</code> / <code>list_*</code>）</td></tr><tr><td><code>sa-token-plugin-*-core</code></td><td><code>sa-token-plugin-common</code>（<code>SaTokenState</code>）</td></tr><tr><td><code>FrameworkAdapter</code></td><td><code>sa_token_adapter::plugin::SaTokenPlugin</code></td></tr><tr><td><code>init_manager</code> 主路径</td><td><code>try_init_manager</code> → <code>Result</code></td></tr><tr><td><code>put_stp_logic</code> / 全局注册</td><td><strong>废弃空操作</strong> — 改用 <code>SaLogic::new</code> / <code>StpUtil::stp_logic</code>（廉价 Clone 门面，无注册表）</td></tr><tr><td>进程内 OAuth2/SSO <code>HashMap</code></td><td>Dao 后端存储</td></tr></tbody></table><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0.1.x</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// use sa_token_plugin_axum_core::SaTokenState;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0.2.0</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sa_token_plugin_common</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 或：use sa_token_plugin_axum::*;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="签名与模块" tabindex="-1">签名与模块 <a class="header-anchor" href="#签名与模块" aria-label="Permalink to &quot;签名与模块&quot;">​</a></h2><p>优先使用 <code>try_build</code> / <code>try_init_manager</code> / <code>try_get_manager</code>。适配器读 token 走 <code>token_io::read_token</code>。登录与授权经 <code>AuthService</code> / <code>AuthzService</code>。多账号用 <code>login_type</code> + <code>SaLogic</code>。<code>StpUtil::login</code> 固定 default；其他体系用 <code>login_with_type</code> / <code>TokenBuilder</code> / <code>SaLogic</code>。</p><p>新增真实路径包括：<code>dao.rs</code>、<code>keys.rs</code>、<code>token_io.rs</code>、<code>codec.rs</code>、<code>service/</code>、<code>stp_logic.rs</code>、<code>oauth2/</code>、<code>sso/</code>、<code>cleanup/</code>、<code>sa-token-plugin-common</code>。Adapter 增加 <code>SaSerializer</code> / <code>SharedSerializer</code>。Dao <strong>没有</strong> <code>set_json</code>；配置错误类型是 <code>ConfigError</code>。</p><h2 id="存储能力-简表" tabindex="-1">存储能力（简表） <a class="header-anchor" href="#存储能力-简表" aria-label="Permalink to &quot;存储能力（简表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Memory</th><th>Redis</th><th>Database</th></tr></thead><tbody><tr><td>基本 KV</td><td>是</td><td>是</td><td>是</td></tr><tr><td><code>get_del</code> / CAS / list / <code>scan</code></td><td>是</td><td>是</td><td><strong>不支持</strong></td></tr></tbody></table><p>nonce 一次性消费、在线索引、多端列表暂勿依赖 database 后端。</p><h2 id="升级清单" tabindex="-1">升级清单 <a class="header-anchor" href="#升级清单" aria-label="Permalink to &quot;升级清单&quot;">​</a></h2><ol><li>所有 <code>sa-token-*</code> 升到 <code>0.2.0</code>。</li><li><code>*-core</code> import 改为 <code>sa-token-plugin-common</code> / 插件 prelude。</li><li><code>init_manager</code> → <code>try_init_manager</code>；库代码用 <code>try_build</code>。</li><li>处理 Token 生成、在线用户、JWT 的 <code>Result</code>。</li><li>仅在需要旧续期时 <code>auto_renew(true)</code>。</li><li>公开路由改用 <code>PathAuthConfig::exclude</code>。</li><li>按需配置 <code>token_prefix</code> / <code>is_write_cookie</code>。</li><li>重读 OAuth2（密钥哈希、PKCE）与 SSO 票据消费。</li><li><code>put_stp_logic</code> → <code>SaLogic::new</code> / <code>StpUtil::stp_logic</code>（注册表已取消；旧 API 为空操作）。</li><li>若需非 JSON 存储编码，启用 <code>fory</code> 并设置 <code>.serializer(...)</code> — 见 <a href="/sa-token-rust/zh/guide/storage.html">存储</a>。</li><li><code>cargo check --workspace</code>，再 <code>cargo clippy --workspace --lib</code>。</li></ol><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/sa-token-rust/zh/guide/quick-start.html">快速入门</a></li><li><a href="/sa-token-rust/zh/guide/path-auth.html">路径鉴权</a></li><li><a href="/sa-token-rust/zh/guide/storage.html">存储</a></li><li><a href="/sa-token-rust/zh/reference/error-reference.html">错误参考</a></li><li>Issues：<a href="https://github.com/sa-tokens/sa-token-rust/issues" target="_blank" rel="noreferrer">https://github.com/sa-tokens/sa-token-rust/issues</a></li></ul>',39)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
